    Run : BOOL;
END_VAR

VAR_OUTPUT
    G : BOOL;
    Y : BOOL;
    R : BOOL;
END_VAR

VAR
    Timer_G : TON;
    Timer_Y : TON;
    Timer_R : TON;
    State : INT := 0;
END_VAR

// Reset all outputs
G := FALSE;
Y := FALSE;
R := FALSE;

IF Run THEN
    CASE State OF
        0: // Green state
            G := TRUE;
            Timer_G(IN := TRUE, PT := T#10s);
            IF Timer_G.Q THEN
                State := 1;
                Timer_G(IN := FALSE);
            END_IF;

        1: // Yellow state
            Y := TRUE;
            Timer_Y(IN := TRUE, PT := T#3s);
            IF Timer_Y.Q THEN
                State := 2;
                Timer_Y(IN := FALSE);
            END_IF;

        2: // Red state
            R := TRUE;
            Timer_R(IN := TRUE, PT := T#13s);
            IF Timer_R.Q THEN
                State := 0;
                Timer_R(IN := FALSE);
            END_IF;
    END_CASE;
ELSE
    // Reset all timers and states when not running
    Timer_G(IN := FALSE);
    Timer_Y(IN := FALSE);
    Timer_R(IN := FALSE);
    State := 0;
END_IF;
END_FUNCTION_BLOCK

