FUNCTION_BLOCK TON
VAR_INPUT
    IN : BOOL;   (* Input trigger *)
    PT : TIME;   (* Preset time *)
END_VAR
VAR_OUTPUT
    Q  : BOOL;   (* Output set after PT *)
    ET : TIME;   (* Elapsed time *)
END_VAR
VAR
    T0 : TIME;   (* Timer start time *)
    Running : BOOL; (* Timer running flag *)
END_VAR

(* Timer logic *)
IF IN THEN
    IF NOT Running THEN
        T0 := TIME();   (* Capture current time *)
        Running := TRUE;
    END_IF;
    ET := TIME() - T0;
    IF ET >= PT THEN
        Q := TRUE;
    ELSE
        Q := FALSE;
    END_IF;
ELSE
    Running := FALSE;
    Q := FALSE;
    ET := T#0s;
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK TON
VAR_INPUT
    IN : BOOL;
    PT : TIME;
END_VAR
VAR_OUTPUT
    Q  : BOOL;
    ET : TIME;
END_VAR
VAR
    T0 : TIME;   // internal elapsed time
END_VAR

// Main logic
IF IN THEN
    // Increment elapsed time
    T0 := T0 + TIME#1ms;  // assuming 1 ms cycle time
    // Check if target time reached
    IF T0 >= PT THEN
        Q  := TRUE;
        ET := PT;
    ELSE
        Q  := FALSE;
        ET := T0;
    END_IF;
ELSE
    // Reset timer
    T0 := TIME#0ms;
    Q  := FALSE;
    ET := TIME#0ms;
END_IF;

END_FUNCTION_BLOCK

