FUNCTION_BLOCK SimplePID
VAR_INPUT
    PV : REAL;   (* Process Variable *)
    SP : REAL;   (* Set Point *)
    Kp : REAL;   (* Proportional Gain *)
    Ki : REAL;   (* Integral Gain *)
    Kd : REAL;   (* Derivative Gain *)
END_VAR
VAR_OUTPUT
    Out : REAL;  (* Controller Output *)
END_VAR
VAR
    integral   : REAL := 0.0;   (* Integral accumulator *)
    prevError  : REAL := 0.0;   (* Previous error value *)
    dt         : REAL := 1.0;   (* Sample time (assumed 1 unit) *)
END_VAR

(* Calculate error *)
VAR
    error : REAL;
    derivative : REAL;
    P_term : REAL;
    I_term : REAL;
    D_term : REAL;
END_VAR

error := SP - PV;

(* Proportional term *)
P_term := Kp * error;

(* Integral term with accumulation *)
integral := integral + error * dt;
I_term := Ki * integral;

(* Derivative term *)
derivative := (error - prevError) / dt;
D_term := Kd * derivative;

(* Compute output *)
Out := P_term + I_term + D_term;

(* Store current error for next cycle *)
prevError := error;

