FUNCTION_BLOCK FB_SimplePID
VAR_INPUT
    PV : REAL;   (* Process Variable *)
    SP : REAL;   (* Set Point *)
    Kp : REAL;   (* Proportional Gain *)
    Ki : REAL;   (* Integral Gain *)
    Kd : REAL;   (* Derivative Gain *)
END_VAR
VAR_OUTPUT
    Out : REAL;  (* Controller Output *)
END_VAR
VAR
    iError : REAL := 0.0;   (* Integral of error *)
    prevError : REAL := 0.0;(* Previous error for derivative *)
    dt : REAL := 1.0;       (* Sample time (assumed 1 unit) *)
END_VAR

    (* Compute error *)
    VAR
        error : REAL;
        dError : REAL;
        pTerm : REAL;
        iTerm : REAL;
        dTerm : REAL;
    END_VAR

    error := SP - PV;
    iError := iError + error * dt;
    dError := (error - prevError) / dt;

    pTerm := Kp * error;
    iTerm := Ki * iError;
    dTerm := Kd * dError;

    Out := pTerm + iTerm + dTerm;

    prevError := error;
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_SimplePID
VAR_INPUT
    PV  : REAL;   (* Process Variable *)
    SP  : REAL;   (* Set Point *)
    Kp  : REAL;   (* Proportional Gain *)
    Ki  : REAL;   (* Integral Gain *)
    Kd  : REAL;   (* Derivative Gain *)
END_VAR
VAR_OUTPUT
    Out : REAL;   (* Controller Output *)
END_VAR
VAR
    error      : REAL;
    prevError  : REAL := 0.0;
    integral   : REAL := 0.0;
    derivative : REAL;
    dt         : REAL := 1.0;  (* Assume 1 second time step; adjust as needed *)
END_VAR

    (* Calculate error *)
    error := SP - PV;

    (* Integral term *)
    integral := integral + error * dt;

    (* Derivative term *)
    derivative := (error - prevError) / dt;

    (* PID output *)
    Out := Kp * error + Ki * integral + Kd * derivative;

    (* Store current error for next cycle *)
    prevError := error;
END_FUNCTION_BLOCK

