FUNCTION_BLOCK FrequencyMeasurement
VAR_INPUT
    Pulse : BOOL;
END_VAR
VAR_OUTPUT
    Freq : REAL;
END_VAR
VAR
    PulsePrev : BOOL := FALSE;
    PulseCount : INT := 0;
    Timer1 : TON;
    TimerIn : BOOL := TRUE;
    RisingEdge : BOOL;
END_VAR

    // Detect rising edge of Pulse
    RisingEdge := Pulse AND NOT PulsePrev;
    PulsePrev := Pulse;

    // Count rising edges within the measurement window
    IF RisingEdge THEN
        PulseCount := PulseCount + 1;
    END_IF;

    // 1-second measurement window using TON timer
    Timer1(IN := TimerIn, PT := T#1S);

    // On window completion: output frequency and reset counter
