VAR
    iState : INT;
    MixingTimer : TON;
END_VAR

(* State Machine Logic *)
CASE iState OF
    0: (* State: Idle *)
        FillValve := FALSE;
        Motor := FALSE;
        DrainValve := FALSE;

        IF Start THEN
            iState := 10;
        END_IF;

    10: (* State: Filling *)
        FillValve := TRUE;
        Motor := FALSE;
        DrainValve := FALSE;

        IF LevelFull THEN
            FillValve := FALSE;
            iState := 20;
        END_IF;

    20: (* State: Mixing *)
        FillValve := FALSE;
        Motor := TRUE;
        DrainValve := FALSE;

        MixingTimer(IN := TRUE, PT := T#10S);

        IF MixingTimer.Q THEN
            MixingTimer(IN := FALSE);
            iState := 30;
        END_IF;

    30: (* State: Emptying *)
        FillValve := FALSE;
        Motor := FALSE;
        DrainValve := TRUE;

        IF LevelEmpty THEN
            DrainValve := FALSE;
            iState := 0;
        END_IF;

END_CASE;

