BEGIN
    Timer(IN := TRUE, PT := SamplingTime);
END_METHOD

METHOD Stop : VOID
BEGIN
    Timer(IN := FALSE);
END_METHOD

METHOD Update : VOID
BEGIN
    CalculateFrequency();
END_METHOD
